<template><AccountShell><div class="flex items-center justify-between gap-3"><div><p class="text-sm font-bold uppercase text-primary-700">Stored on this device</p><h1 class="text-3xl font-black text-ink">Recently Viewed</h1></div><button v-if="entries.length" class="rounded-xl border border-slate-200 px-4 py-2 text-sm font-bold" @click="clear">Clear</button></div><p class="mt-2 text-sm text-slate-500">Up to 30 deduplicated products, newest first. The stored payload is ready for a future authenticated sync.</p><LoadingSkeleton v-if="loading" class="mt-6 h-48"/><EmptyState v-else-if="!products.length" class="mt-6" title="Nothing viewed yet" message="Products you open will appear here."/><ProductGrid v-else class="mt-6" :products="products"/></AccountShell></template>
<script setup>
import { computed, onMounted, ref } from 'vue';import AccountShell from './partials/AccountShell.vue';import ProductGrid from '../../components/product/ProductGrid.vue';import EmptyState from '../../components/common/EmptyState.vue';import LoadingSkeleton from '../../components/common/LoadingSkeleton.vue';import { useRecentlyViewedStore } from '../../stores/recentlyViewedStore';import { productService } from '../../services/productService'
const store=useRecentlyViewedStore(),entries=computed(()=>store.items),products=ref([]),loading=ref(true);async function load(){products.value=(await Promise.all(store.items.map(item=>productService.find(item.slug).catch(()=>null)))).filter(Boolean);loading.value=false}function clear(){store.clear();products.value=[]}onMounted(load)
</script>
